Insert into MsgError (MsgID, MsgGroupID, MsgNameEN, MsgNameCT, MsgNameCS, MsgNameJP, MsgNameTH, MsgNameKO, MsgNameES, MsgNameVI, IsActive) values (10001,2,'Wrong Min bet/ Max bet/ Max per match/ Credit/ Master Agent name/ user group', N'最低投注/最高投注/單場最高投注/信用額度/總代理名/組別不正確.', N'最低投注/最高投注/单场最高投注/信用额度/总代理名/组别不正确.', N'Wrong Min bet/ Max bet/ Max per match/ Credit/ Master Agent name/ user group.', N'การกำหนดจำนวนเงินสำหรับการวางเดิมพันต่ำสุด/ สูงสุด/เครดิต/ชื่อตัวแทนหลัก/กลุ่มลูกค้าที่ใช้บริการ ไม่ถูกต้อง.', N'잘못된 최소 배팅/ 최대 배팅/경기당 최대/크레딧/마스터 에이전트 이름/ 사용자 그룹.', N'Wrong Min bet/ Max bet/ Max per match/ Credit/ Master Agent name/ user group', N'Sai giá trị : Tiền cược nhỏ nhất / Tiền cược lớn nhất / Tiền cược lớn nhất cho mỗi trận đấu / Mức tín dụng / Tên của Master / Nhóm người chơi.',1)
