Insert into MsgError (MsgID, MsgGroupID, MsgNameEN, MsgNameCT, MsgNameCS, MsgNameJP, MsgNameTH, MsgNameKO, MsgNameES, MsgNameVI, IsActive) values (10012,2,'Min bet must be equal to or greater than Super/Master/Agent min bet', N'對不起,最低投注需相等於或少於超級總代理最低投注', N'对不起，最低投注需相等于或少于超级总代理最低投注', N' Min bet must be equal to or greater than Super/Master/Agent min bet', N'ขออภัย จำนวนเงินในการเล่นขั้นต่ำ ต้องเท่ากับ หรือ มากกว่าขั้นต่ำที่กำหนดไว้ ของ ตัวแทนสูงสุด/ ตัวแทนหลัก/ ตัวแทนย่อย', N'죄송합니다. 최소 배팅은 슈퍼/마스터/에이젼트 최소 배팅보다 많아야 합니다 ', N' Min bet must be equal to or greater than Super/Master/Agent min bet', N'Tiền cược nhỏ nhất của người chơi phải lớn hơn hoặc bằng của Super/ Master/ Agent.',1)
Insert into MsgError (MsgID, MsgGroupID, MsgNameEN, MsgNameCT, MsgNameCS, MsgNameJP, MsgNameTH, MsgNameKO, MsgNameES, MsgNameVI, IsActive) values (10013,2,'Max bet must be equal to or less than Master/Agent max bet', N'對不起,最高投注需相等於或少於總代理/代理最高投注', N'对不起，最高投注需相等于或少于总代理/代理最高投注', N' Max bet must be equal to or less than Master/Agent max bet', N'ขออภัย จำนวนเงินสูงสุดที่สามารถเล่นได้ ต้องเท่ากับ หรือ  น้อยกว่า จำนวนเงินสูงสุดที่กำหนดไว้ของตัวแทนหรือตัวแทนหลัก', N'죄송합니다. 최대 배팅은 마스터/ 에이전트의 최대 배팅 이하이여야 합니다', N' Max bet must be equal to or less than Master/Agent max bet', N'Tiền cược lớn nhất của người chơi phải nhỏ hơn hoặc bằng của Master/ Agent.',1)
