Insert into MsgError (MsgID, MsgGroupID, MsgNameEN, MsgNameCT, MsgNameCS, MsgNameJP, MsgNameTH, MsgNameKO, MsgNameES, MsgNameVI, IsActive) values (70001,8,'Update max credit unsuccessfully. The new max credit must be greater than or equal to the total credit of current members.', N'更新最高信用不成功。新的最高信用必须大于或等于总现任会员的信用。', N'更新最高信用不成功。新的最高信用必须大于或等于总现任会员的信用。', N'Update max credit unsuccessfully. The new max credit must be greater than or equal to the total credit of current members.', N'การอัพเดทเครดิตสูงสุดไม่สำเร็จ. เครดิตสูงสุดต้องมากกว่าหรือเท่ากับเครดิตของสมาชิกทั้งหมด', N'Update max credit unsuccessfully. The new max credit must be greater than or equal to the total credit of current members.', N'Update max credit unsuccessfully. The new max credit must be greater than or equal to the total credit of current members.', N'Thiết lập hạn mức tín dụng tối đa  thất bại .Giá trị mới phải lớn hơn hoặc bằng tổng mức tín dụng đã cấp cho các thành viên.',1)
Insert into MsgError (MsgID, MsgGroupID, MsgNameEN, MsgNameCT, MsgNameCS, MsgNameJP, MsgNameTH, MsgNameKO, MsgNameES, MsgNameVI, IsActive) values (70002,8,'Update max credit unsuccessfully. The new max credit must be less than or equal to the credit of this agent.', N'更新最高信用不成功。新的最高信用必須小於或等於總現任代理的信用。', N'更新最高信用不成功。新的最高信用必须小于或等于总现任代理的信用。', N'Update max credit unsuccessfully. The new max credit must be less than or equal to the credit of this agent.', N'การอัพเดทเครดิตสูงสุดไม่สำเร็จ. เครดิตสูงสุดต้องน้อกว่าหรือเท่ากับเครดิตของเอเย่นทั้งหมด', N'Update max credit unsuccessfully. The new max credit must be less than or equal to the credit of this agent.', N'Update max credit unsuccessfully. The new max credit must be less than or equal to the credit of this agent.', N'Thiết lập hạn mức tín dụng tối đa thất bại .Giá trị mới phải nhỏ hơn hoặc bằng với hạn mức của Agent này.',1)
Insert into MsgError (MsgID, MsgGroupID, MsgNameEN, MsgNameCT, MsgNameCS, MsgNameJP, MsgNameTH, MsgNameKO, MsgNameES, MsgNameVI, IsActive) values (70003,8,'Sorry, credit increase unsuccessful. You have exceeded your agent credit.', N'對不起,無法增加信用額.您的信用額已超出您的代理限額.', N'对不起无法增加信用额度已超出您的代理限额.', N'Sorry, credit increase unsuccessful. You have exceeded your agent credit.', N'ขอโทษค่ะ เครดิตของคุณมีปัญหา.', N'죄송합니다. 크레딧 증가에 실패했습니다. 해당 에이전트의 크레딧을 초과 했습니다.', N'Sorry, credit increase unsuccessful. You have exceeded your agent credit.', N'Rất tiếc, không thể tăng mức tín dụng trong tài khoản. Tài khoản đã vượt quá số tín dụng hiện có của Agent.',1)
Insert into MsgError (MsgID, MsgGroupID, MsgNameEN, MsgNameCT, MsgNameCS, MsgNameJP, MsgNameTH, MsgNameKO, MsgNameES, MsgNameVI, IsActive) values (70004,8,'Sorry, credit update unsuccessful. The new master credit cannot be less than total agent given credit.', N'Sorry, credit update unsuccessful. The new master credit cannot be less than total agent given credit.', N'Sorry, credit update unsuccessful. The new master credit cannot be less than total agent given credit.', N'Sorry, credit update unsuccessful. The new master credit cannot be less than total agent given credit.', N'Sorry, credit update unsuccessful. The new master credit cannot be less than total agent given credit.', N'죄송합니다. 크레딧 업데이트에 실패 했습니다. 새로운 마스터 크레딧은 총에이전트 크레딧보다 높을 수 없습니다.', N'Sorry, credit update unsuccessful. The new master credit cannot be less than total agent given credit.', N'Rất tiếc, thiết lập mức tín dụng thất bại .Giá trị mới được thiết lập cho Master không thể ít hơn tổng hạn mức đã cấp cho các Agent.',1)
Insert into MsgError (MsgID, MsgGroupID, MsgNameEN, MsgNameCT, MsgNameCS, MsgNameJP, MsgNameTH, MsgNameKO, MsgNameES, MsgNameVI, IsActive) values (70005,8,'Sorry, update credit unsuccessfully. The new agent credit must be greater than or equal to total member given credit.', N'Sorry, update credit unsuccessfully. The new agent credit must be greater than or equal to total member given credit.', N'Sorry, update credit unsuccessfully. The new agent credit must be greater than or equal to total member given credit.', N'Sorry, update credit unsuccessfully. The new agent credit must be greater than or equal to total member given credit.', N'Sorry, update credit unsuccessfully. The new agent credit must be greater than or equal to total member given credit.', N'Sorry, update credit unsuccessfully. The new agent credit must be greater than or equal to total member given credit.', N'Sorry, update credit unsuccessfully. The new agent credit must be greater than or equal to total member given credit.', N'Rất tiếc, thiết lập mức tín dụng cho tài khoản thất bại .Giá trị mới được thiết lập cho Agent phải lớn hơn hoặc bằng tổng hạn mức được cấp của các thành viên.',1)
Insert into MsgError (MsgID, MsgGroupID, MsgNameEN, MsgNameCT, MsgNameCS, MsgNameJP, MsgNameTH, MsgNameKO, MsgNameES, MsgNameVI, IsActive) values (70006,8,'Cannot reduce credit. Member outstanding exceeded.', N'對不起，無法修改信用額度。已超出會員未完成交易。', N'对不起，无法修改信用额度。已超出会员未完成交易。', N'Cannot reduce credit. Member outstanding exceeded.', N'ไม่สามารถทำรายการลดเครดิตได้ ลูกค้ามียอดรายการคงค้างเกินบัญชี.', N'수정 할 수있는 크레딧이 없습니다. 배팅되어있는 금액만 남아 있습니다.', N'Cannot reduce credit. Member outstanding exceeded.', N'Không thể hạ mức tín dụng trong tài khoản. Số tiền chưa xử lý của Member đã vượt quá múc tín dụng hiện có trong tài khoản.',1)
Insert into MsgError (MsgID, MsgGroupID, MsgNameEN, MsgNameCT, MsgNameCS, MsgNameJP, MsgNameTH, MsgNameKO, MsgNameES, MsgNameVI, IsActive) values (70007,8,'Sorry, increase credit unsuccessfully.\nYou have exceeded the agent''s member max credit', N'對不起,更新信用額度不成功, 已超出會員最高信用額度', N'对不起，更新信用额度不成功，已超出会员信用额度', N'Sorry, increase credit unsuccessfully.\nYou have exceeded the agent''s member max credit', N'ขออภัย  การเพิ่มจำนวนยอดเงินในบัญชี ไม่เป็นผล เนื่องจากคุณได้มียอดเกินจำนวนเงินสูงสุดในบัญชีของสมาชิกคะ', N'죄송합니다. 크레딧 증가에 실패했습니다. 회원님의 최대 크레딧을 초과 했습니다', N'Sorry, increase credit unsuccessfully.\nYou have exceeded the agent''s member max credit', N'Rất tiếc, không thể tăng mức tín dụng trong tài khoản.\n Bạn đã  vượt quá mức quy định tối đa cho mỗi thành viên của Agent',1)
Insert into MsgError (MsgID, MsgGroupID, MsgNameEN, MsgNameCT, MsgNameCS, MsgNameJP, MsgNameTH, MsgNameKO, MsgNameES, MsgNameVI, IsActive) values (70008,8,'Sorry, the [Clear All Credit] function is temporarily unavailable!\nThe account was still closed already.', N'Sorry, the [Clear All Credit] function is temporarily unavailable!\nThe account was still closed already.', N'Sorry, the [Clear All Credit] function is temporarily unavailable!\nThe account was still closed already.', N'Sorry, the [Clear All Credit] function is temporarily unavailable!\nThe account was still closed already.', N'Sorry, the [Clear All Credit] function is temporarily unavailable!\nThe account was still closed already.', N'Sorry, the [Clear All Credit] function is temporarily unavailable!\nThe account was still closed already.', N'Sorry, the [Clear All Credit] function is temporarily unavailable!\nThe account was still closed already.', N'Rất tiếc, chức năng thanh lý tín dụng trong tài khoản hiện bị khóa.\n Tài khoản vẫn đang bị khóa.',1)
Insert into MsgError (MsgID, MsgGroupID, MsgNameEN, MsgNameCT, MsgNameCS, MsgNameJP, MsgNameTH, MsgNameKO, MsgNameES, MsgNameVI, IsActive) values (70009,8,'Sorry, increase credit unsuccessfully, You have exceeded the member max credit.', N'對不起,更新信用額度不成功, 已超出會員最高信用額度.', N'对不起，更新信用额度不成功，已超出会员信用额度.', N'Sorry, increase credit unsuccessfully, You have exceeded the member max credit.', N'ขออภัย  การเพิ่มจำนวนยอดเงินในบัญชี ไม่เป็นผล เนื่องจากคุณได้มียอดเกินจำนวนเงินสูงสุดในบัญชีของสมาชิกคะ.', N'죄송합니다. 크레딧 증가에 실패했습니다. 회원님의 최대 크레딧을 초과 했습니다.', N'Sorry, increase credit unsuccessfully, You have exceeded the member max credit.', N'Rất tiếc, không thể tăng mức tín dụng trong tài khoản. Bạn đã  vượt quá mức quy định tối đa cho mỗi thành viên.',1)
Insert into MsgError (MsgID, MsgGroupID, MsgNameEN, MsgNameCT, MsgNameCS, MsgNameJP, MsgNameTH, MsgNameKO, MsgNameES, MsgNameVI, IsActive) values (70010,8,'Sorry, credit update is not successful, You have exceeded your super agent credit.', N'對不起,更新信用額度不成功, 已超出超級總代理信用額度.', N'对不起，更新信用额度不成功，已超出超级总代理信用额度.', N'Sorry, credit update is not successful, You have exceeded your super agent credit.', N'ขออภัย การเพิ่มจำนวนยอดเงินในบัญชี ไม่เป็นผล เนื่องจาก คุณได้มียอดเกินจำนวนเงินสูงสุดในบัญชีของตัวแทนสูงสุดคะ.', N'죄송합니다. 크레딧 업데이트에 실패했습니다, 해당 슈터 에이전트의 크레딧을 초과 했습니다.', N'Sorry, credit update is not successful, You have exceeded your super agent credit.', N'Rất tiếc, thiết lập giá trị tín dụng cho tài khoản thất bại .Tài khoản đã vượt quá mức tín dụng hiện có của Super.',1)
Insert into MsgError (MsgID, MsgGroupID, MsgNameEN, MsgNameCT, MsgNameCS, MsgNameJP, MsgNameTH, MsgNameKO, MsgNameES, MsgNameVI, IsActive) values (70011,8,'Sorry, credit update is not successful, You have exceeded your master credit.', N'對不起,更新信用額度不成功, 已超出總代理信用額度.', N'对不起，更新信用额度不成功，已超出总代理信用额度.', N'Sorry, credit update is not successful, You have exceeded your master credit.', N'ขออภัย การปรับยอดเงินในบัญชี ไม่เป็นผล เนื่องจากคุณมียอดเกินจำนวนเงินสูงสุดในบัญชีของตัวแทนหลักคะ.', N'죄송합니다. 크레딧 업데이트에 실패했습니다, 해당 마스터 크레딧을 초과 했습니다.', N'Sorry, credit update is not successful, You have exceeded your master credit.', N'Rất tiếc, thiết lập giá trị tín dụng cho tài khoản thất bại .Tài khoản đã vượt quá mức tín dụng hiện có của Master.',1)
Insert into MsgError (MsgID, MsgGroupID, MsgNameEN, MsgNameCT, MsgNameCS, MsgNameJP, MsgNameTH, MsgNameKO, MsgNameES, MsgNameVI, IsActive) values (70012,8,'Sorry, credit update is not successful, You have exceeded your agent credit.', N'對不起, 更新信用額度不成功, 已超出代理信用額度.', N'对不起， 更新信用额度不成功， 已超出代理信用额度.', N'Sorry, credit update is not successful, You have exceeded your agent credit.', N'ขออภัย การเพิ่มจำนวนยอดเงินในบัญชี ไม่เป็นผล เนื่องจากคุณได้มียอดเกินจำนวนเงินในบัญชีของตัวแทนคะ.', N'Sorry, credit update is not successful, You have exceeded your agent credit.', N'Sorry, credit update is not successful, You have exceeded your agent credit.', N'Rất tiếc, thiết lập giá tín dụng cho tài khoản thất bại. Tài khoản đã vượt quá mức tín dụng hiện có  của Agent.',1)
Insert into MsgError (MsgID, MsgGroupID, MsgNameEN, MsgNameCT, MsgNameCS, MsgNameJP, MsgNameTH, MsgNameKO, MsgNameES, MsgNameVI, IsActive) values (70013,8,'Sorry, credit increase is unsuccessful, You have exceeded member max credit given by your upline', N'對不起,更新信用額度不成功, 已超出會員最高信用額度', N'对不起，更新信用额度不成功，已超出会员信用额度', N'Sorry, credit increase is unsuccessful, You have exceeded member max credit given by your upline', N'ขออภัย  การเพิ่มจำนวนยอดเงินในบัญชี ไม่เป็นผล เนื่องจากคุณได้มียอดเกินจำนวนเงินสูงสุดในบัญชีของสมาชิกคะ', N'Sorry, credit increase is unsuccessful, You have exceeded member max credit given by your upline', N'Sorry, credit increase is unsuccessful, You have exceeded member max credit given by your upline', N'Rất tiếc, không thể tăng mức tín dụng cho tài khoản. Tài khoản đã vượt quá mức quy định tối đa cho mỗi thành viên được thiết lập bởi cấp trên',1)
Insert into MsgError (MsgID, MsgGroupID, MsgNameEN, MsgNameCT, MsgNameCS, MsgNameJP, MsgNameTH, MsgNameKO, MsgNameES, MsgNameVI, IsActive) values (70014,8,'Cannot reduce credit. Member outstanding exceeded.', N'降低信用額度不成功,超過會員未完成交易.', N'降低信用额度不成功，超过会员未完成交易.', N'Cannot reduce credit. Member outstanding exceeded.', N'ไม่สามารถทำรายการลดเครดิตได้ ลูกค้ามียอดรายการคงค้างเกินบัญชี.', N'수정 할 수있는 크레딧이 없습니다. 배팅되어있는 금액만 남아 있습니다.', N'Cannot reduce credit. Member outstanding exceeded.', N'Không thể hạ mức tín dụng trong tài khoản. Số tiển chưa sử lý của Member đã vượt quá mức tín dụng trong tài khoản',1)
Insert into MsgError (MsgID, MsgGroupID, MsgNameEN, MsgNameCT, MsgNameCS, MsgNameJP, MsgNameTH, MsgNameKO, MsgNameES, MsgNameVI, IsActive) values (70015,8,'Max credit update not successful, The new max credit is less than the credit of the current members', N'更新最高信用額度不成功, 新的最高信用額度少於會員現有信用額度.', N'更新最高信用额度不成功，新的最高信用额度少于会员现有信用额度.', N'Max credit update not successful, The new max credit is less than the credit of the current members', N'ปรับยอดรายการเครดิตสูงสุดไม่เป็นผล ยอดรายการเครดิตใหม่ต้องน้อยกว่า ยอดรายการเครดิตของสมาชิกปัจจุบัน.', N'최대 크래딧 업데이트에 실패 했습니다, 새로운 최대 크레딧은 현재 회원님의 크래딧보다 작습니다.', N'Max credit update not successful, The new max credit is less than the credit of the current members', N'Thiết lập hạn mức tín dụng tối đa cho tài khoản thất bại .Giá trị mới ít hơn mức tín dụng hiện có của các thành viên',1)
Insert into MsgError (MsgID, MsgGroupID, MsgNameEN, MsgNameCT, MsgNameCS, MsgNameJP, MsgNameTH, MsgNameKO, MsgNameES, MsgNameVI, IsActive) values (70016,8,'Max credit update not successful, The new max credit is greater than the credit of the agent', N'更新最高信用額度不成功, 新的最高信用額度已超出代理信用額度.', N'更新最高信用额度不成功，新的最高信用额度已超出代理信用额度.', N'Max credit update not successful, The new max credit is greater than the credit of the agent', N'ปรับยอดรายการเครดิตสูงสุดไม่เป็นผล ยอดรายการเครดิตใหม่ต้องไม่มากกว่า ยอดรายการเครดิตของตัวแทน.', N'최대 크래딧 업데이트에 실패 했습니다,  새로운 최대 크래딧은 에이전트의 크레딧보다 큽니다.', N'Max credit update not successful, The new max credit is greater than the credit of the agent', N'Thiết lập hạn mức tín dụng tối đa cho tài khoản thất bại .Giá trị mới lớn hơn mức tín dụng hiện có của  Agent',1)
Insert into MsgError (MsgID, MsgGroupID, MsgNameEN, MsgNameCT, MsgNameCS, MsgNameJP, MsgNameTH, MsgNameKO, MsgNameES, MsgNameVI, IsActive) values (70017,8,'Credit update not successful, The new credit is not enough for all current members', N'更新信用額度不成功, 信額度不足夠給所有會員.', N'更新信用額度不成功, 信額度不足夠給所有會員.', N'Credit update not successful, The new credit is not enough for all current members', N'Credit update not successful, The new credit is not enough for all current members', N'크레딧 업데이트에 실패했습니다. 현재 회원의 크레딧이 충분하지 않습니다.', N'Credit update not successful, The new credit is not enough for all current members', N'Thiết lập mức tín dụng cho tài khoản thất bại .Giá trị mới được thiết lập không  đủ cho tất cả các Member hiện tại',1)
Insert into MsgError (MsgID, MsgGroupID, MsgNameEN, MsgNameCT, MsgNameCS, MsgNameJP, MsgNameTH, MsgNameKO, MsgNameES, MsgNameVI, IsActive) values (70018,8,'Credit update not successful, The new credit is not enough for all current agents', N'更新信用額度不成功, 信額度不足夠給所有代理.', N'更新信用额度不成功， 信用额度不足够给所有代理.', N'Credit update not successful, The new credit is not enough for all current agents', N'ปรับยอดเครดิตไม่สมบูรณ์ เนื่องจากยอดเครดิตใหม่ไม่เพียงพอสำหรับตัวแทนทุกคน.', N'크레딧 업데이트에 실패했습니다.  현재 에이전트의 크레딧이 충분하지 않습니다.', N'Credit update not successful, The new credit is not enough for all current agents', N'Thiết lập mức tín dụng cho tài khoản thất bại .Giá trị mới được thiết lập không đủ cho tất cả các Agent hiện tại',1)
