Insert into MsgError (MsgID, MsgGroupID, MsgNameEN, MsgNameCT, MsgNameCS, MsgNameJP, MsgNameTH, MsgNameKO, MsgNameES, MsgNameVI, IsActive) values (70021,8,'Credit update not successful, You have exceeded your agent credit.', N'更新信用額度不成功, 已超出代理信用額度.', N'更新信用额度不成功， 已超出代理信用额度.', N'Credit update not successful, You have exceeded your agent credit.', N'ปรับยอดเครดิตไม่สมบูรณ์ เนื่องจากคุณมียอดเครดิตของตัวแทนมากเกินไป.', N'크레딧 업데이트에 실패했습니다. 해당 에이전트의 크레딧을 초과 했습니다.', N'Credit update not successful, You have exceeded your agent credit.', N'Thiết lập mức tín dụng cho tài khoản thất bại. Tài khoản đã vượt quá số tín dụng hiện có của Agent.',1)
